 if($a==='cart'){$uid=auth();if($m==='GET'){$s=$pdo->prepare('SELECT ci.product_id,ci.quantity,p.name,p.price,p.currency,p.image_url,p.stock_quantity FROM carts c JOIN cart_items ci ON ci.cart_id=c.id JOIN products p ON p.id=ci.product_id WHERE c.user_id=?');$s->execute([$uid]);out(['success'=>true,'data'=>$s->fetchAll()]);}method('POST','PATCH','DELETE');checkCsrf();$d=input();$pid=(int)($d['product_id']??0);$pdo->beginTransaction();$s=$pdo->prepare('INSERT INTO carts(user_id) VALUES(?) ON DUPLICATE KEY UPDATE id=LAST_INSERT_ID(id)');$s->execute([$uid]);$cid=(int)$pdo->lastInsertId();if($m==='DELETE'){$s=$pdo->prepare('DELETE FROM cart_items WHERE cart_id=? AND product_id=?');$s->execute([$cid,$pid]);}else{$qty=(int)($d['quantity']??1);$s=$pdo->prepare('SELECT stock_quantity,is_active FROM products WHERE id=? FOR UPDATE');$s->execute([$pid]);$p=$s->fetch();if(!$p||!$p['is_active']||$qty<1||$qty>50||$qty>$p['stock_quantity']){$pdo->rollBack();out(['success'=>false,'error'=>'Article indisponible ou quantité invalide.'],409);}$s=$pdo->prepare('INSERT INTO cart_items(cart_id,product_id,quantity) VALUES(?,?,?) ON DUPLICATE KEY UPDATE quantity=VALUES(quantity)');$s->execute([$cid,$pid,$qty]);}$pdo->commit();out(['success'=>true]);}
 if($a==='orders'&&$m==='POST'){$uid=auth();checkCsrf();$d=input();$pay=$d['payment_method']??'';if(!in_array($pay,['cash','mobile_money','credit'],true))out(['success'=>false,'error'=>'Mode de paiement invalide.'],422);$pdo->beginTransaction();$s=$pdo->prepare('SELECT credit_eligible FROM users WHERE id=? FOR UPDATE');$s->execute([$uid]);if($pay==='credit'&&!$s->fetchColumn()){$pdo->rollBack();out(['success'=>false,'error'=>'Crédit non autorisé par la boutique.'],403);}$s=$pdo->prepare('SELECT ci.product_id,ci.quantity,p.name,p.price,p.stock_quantity,p.is_active FROM carts c JOIN cart_items ci ON ci.cart_id=c.id JOIN products p ON p.id=ci.product_id WHERE c.user_id=? FOR UPDATE');$s->execute([$uid]);$items=$s->fetchAll();if(!$items){$pdo->rollBack();out(['success'=>false,'error'=>'Panier vide.'],422);}$total=0;foreach($items as $i){if(!$i['is_active']||$i['quantity']>$i['stock_quantity']){$pdo->rollBack();out(['success'=>false,'error'=>'Stock insuffisant.'],409);}$total+=(float)$i['price']*(int)$i['quantity'];}$num='ES'.date('ymd').strtoupper(bin2hex(random_bytes(4)));$s=$pdo->prepare('INSERT INTO orders(user_id,order_number,payment_method,payment_status,total_amount,customer_note) VALUES(?,?,?,?,?,?)');$s->execute([$uid,$num,$pay,$pay==='credit'?'pending':'unpaid',$total,trim($d['customer_note']??'')?:null]);$oid=(int)$pdo->lastInsertId();$line=$pdo->prepare('INSERT INTO order_items(order_id,product_id,product_name,unit_price,quantity,line_total) VALUES(?,?,?,?,?,?)');$stock=$pdo->prepare('UPDATE products SET stock_quantity=stock_quantity-? WHERE id=? AND stock_quantity>=?');foreach($items as $i){$line->execute([$oid,$i['product_id'],$i['name'],$i['price'],$i['quantity'],(float)$i['price']*(int)$i['quantity']]);$stock->execute([$i['quantity'],$i['product_id'],$i['quantity']]);if(!$stock->rowCount()){$pdo->rollBack();out(['success'=>false,'error'=>'Stock modifié, recommencez.'],409);}}$s=$pdo->prepare('DELETE ci FROM cart_items ci JOIN carts c ON c.id=ci.cart_id WHERE c.user_id=?');$s->execute([$uid]);$pdo->commit();out(['success'=>true,'order'=>['id'=>$oid,'order_number'=>$num,'total_amount'=>$total,'payment_method'=>$pay,'payment_status'=>$pay==='credit'?'pending':'unpaid']],201);}
 if($a==='orders'&&$m==='GET'){$s=$pdo->prepare('SELECT id,order_number,status,payment_method,payment_status,total_amount,currency,created_at FROM orders WHERE user_id=? ORDER BY created_at DESC');$s->execute([auth()]);out(['success'=>true,'data'=>$s->fetchAll()]);}
 if(str_starts_with($a,'admin/')){admin();if($m!=='GET')checkCsrf();
