  if($a==='admin/products'&&in_array($m,['POST','PATCH'],true)){$d=input();$n=trim($d['name']??'');$price=(float)($d['price']??-1);$stock=(int)($d['stock_quantity']??0);if(!$n||$price<0||$stock<0)out(['success'=>false,'error'=>'Données produit invalides.'],422);if($m==='POST'){$s=$pdo->prepare('INSERT INTO products(category_id,name,description,price,currency,image_url,stock_quantity,is_active) VALUES(?,?,?,?,?,?,?,?)');$s->execute([$d['category_id']?:null,$n,$d['description']??null,$price,$d['currency']??'USD',$d['image_url']??null,$stock,!empty($d['is_active'])?1:0]);out(['success'=>true,'id'=>(int)$pdo->lastInsertId()],201);}$s=$pdo->prepare('UPDATE products SET category_id=?,name=?,description=?,price=?,currency=?,image_url=?,stock_quantity=?,is_active=? WHERE id=?');$s->execute([$d['category_id']?:null,$n,$d['description']??null,$price,$d['currency']??'USD',$d['image_url']??null,$stock,!empty($d['is_active'])?1:0,(int)$d['id']]);out(['success'=>true]);}
